using ModelContextProtocol.Server;
using System.ComponentModel;

namespace McpServer.Tools;

[McpServerToolType]
public sealed class ApiFetchTool
{
    [McpServerTool, Description("Fetches data from an external API endpoint and returns the JSON response.")]
    public static async Task<string> FetchApiData(
        IHttpClientFactory httpClientFactory,
        [Description("The relative path to request (e.g. /users/1).")] string path,
        CancellationToken cancellationToken)
    {
        using var client = httpClientFactory.CreateClient("ExternalApi");
        var response = await client.GetAsync(path, cancellationToken);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadAsStringAsync(cancellationToken);
    }
}

using Microsoft.Extensions.AI;
using ModelContextProtocol.Server;
using System.ComponentModel;

namespace McpServer.Prompts;

[McpServerPromptType]
public static class SummarizationPrompts
{
    [McpServerPrompt, Description("Generates a prompt that asks the model to summarize the provided text.")]
    public static IEnumerable<ChatMessage> Summarize(
        [Description("The text to summarize.")] string text,
        [Description("Desired length: brief, detailed, or bullet-points.")] string style = "brief")
    {
        return
        [
            new(ChatRole.User,
                $"""
                Summarize the following text. Use a "{style}" style.

                Text:
                {text}
                """),
            new(ChatRole.Assistant,
                "I'll provide a clear, accurate summary in the requested style.")
        ];
    }
}

